class PanelQuad {
    char padding[0x194];

public:
    virtual ~PanelQuad();
    virtual void Init();
    virtual void TurnOn(bool on);
};

class BeachFrontEnd {
    char padding[0x9d8];
    PanelQuad* here[25];
    PanelQuad* selected[25];
    PanelQuad* open[25];
    PanelQuad* done[25];
    PanelQuad* select_circle[25][3];
    PanelQuad* new_open_circle[25][3];

public:
    static const int max_blink_index = 3;
    void HideAllDots();
};

void BeachFrontEnd::HideAllDots()
{
	for(int i=0; i<25; i++)
  {
		for(int j=0; j<max_blink_index; j++)
    {
      if(new_open_circle[i][j])   new_open_circle[i][j]->TurnOn(false);
      if(select_circle[i][j])     select_circle[i][j]->TurnOn(false);
    }
    if(here[i])       here[i]->TurnOn(false);;
    if(selected[i])   selected[i]->TurnOn(false);;
    if(open[i])       open[i]->TurnOn(false);;
    if(done[i])       done[i]->TurnOn(false);;
  }

}
